4: use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
5: use std::sync::Arc;
6: 
7: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
8: enum Currency {
9:     Eur,
10:     Usd,
11:     Gbp,
12: }
13: 
14: impl Currency {
15:     fn from_code(code: &str) -> Option<Self> {
16:         match code {
17:             "EUR" => Some(Self::Eur),
18:             "USD" => Some(Self::Usd),
19:             "GBP" => Some(Self::Gbp),
20:             _ => None,
21:         }
22:     }
23: }
24: 
25: #[derive(Debug, Clone, PartialEq, Eq)]
26: enum TxStatus {
27:     Initiated,
28:     Settled,
29:     Rejected,
30: }
31: 
32: #[derive(Debug, Clone)]
33: struct PaymentTx {
34:     id: u64,
35:     account_id: u64,
36:     amount_cents: u64,
37:     currency: Currency,
38:     status: TxStatus,
39: }
40: 
41: struct AntifraudEngine {
42:     max_amount_cents: u64,
43: }
44: 
45: impl AntifraudEngine {
46:     fn new(max_amount_cents: u64) -> Self {
47:         Self { max_amount_cents }
48:     }
49: 
50:     fn evaluate(&self, amount_cents: u64) -> bool {
51:         amount_cents <= self.max_amount_cents
52:     }
53: }
54: 
55: struct PaymentProcessor {
56:     antifraud: AntifraudEngine,
57:     settled_count: AtomicUsize,
58:     rejected_count: AtomicUsize,
59:     total_volume_cents: AtomicU64,
60: }
61: 
62: impl PaymentProcessor {
63:     fn new(max_amount_cents: u64) -> Self {
64:         Self {
65:             antifraud: AntifraudEngine::new(max_amount_cents),
66:             settled_count: AtomicUsize::new(0),
67:             rejected_count: AtomicUsize::new(0),
68:             total_volume_cents: AtomicU64::new(0),
69:         }
70:     }
71: 
72:     fn process(&self, mut tx: PaymentTx) -> PaymentTx {
73:         if !self.antifraud.evaluate(tx.amount_cents) {
74:             tx.status = TxStatus::Rejected;
75:             self.rejected_count.fetch_add(1, Ordering::SeqCst);
76:         } else {
77:             tx.status = TxStatus::Settled;
78:             self.settled_count.fetch_add(1, Ordering::SeqCst);
79:             self.total_volume_cents.fetch_add(tx.amount_cents, Ordering::SeqCst);
80:         }
81:         tx
82:     }
83: }
84: 
85: fn run_validation_suite() {
86:     let eur = Currency::from_code("EUR");
87:     assert_eq!(eur, Some(Currency::Eur));
88:     let invalid = Currency::from_code("XYZ");
89:     assert_eq!(invalid, None);
90: 
91:     let processor = PaymentProcessor::new(100_000);
92:     let valid_tx = PaymentTx {
93:         id: 1,
94:         account_id: 42,
95:         amount_cents: 50_000,
96:         currency: Currency::Eur,
97:         status: TxStatus::Initiated,
98:     };
99:     let res = processor.process(valid_tx);
100:     assert_eq!(res.status, TxStatus::Settled);
101:     assert_eq!(res.id, 1);
102:     assert_eq!(res.account_id, 42);
103:     assert_eq!(res.currency, Currency::Eur);
104: 
105:     let fraud_tx = PaymentTx {
106:         id: 2,
107:         account_id: 42,
108:         amount_cents: 200_000,
109:         currency: Currency::Eur,
110:         status: TxStatus::Initiated,
111:     };
112:     let res_fraud = processor.process(fraud_tx);
113:     assert_eq!(res_fraud.status, TxStatus::Rejected);
114:     assert_eq!(res_fraud.id, 2);
115:     assert_eq!(res_fraud.account_id, 42);
116:     assert_eq!(res_fraud.currency, Currency::Eur);
117: }
118: 
119: fn run_concurrent_benchmark(processor: &Arc<PaymentProcessor>) {
120:     let thread_count = 4;
121:     let tx_per_thread = 250;
122:     let mut handles = Vec::with_capacity(thread_count);
123: 
124:     for t_idx in 0..thread_count {
125:         let proc = Arc::clone(processor);
126:         handles.push(std::thread::spawn(move || {
127:             for i in 0..tx_per_thread {
128:                 let amount = if i % 10 == 0 { 150_000 } else { 1_000 };
129:                 let tx = PaymentTx {
130:                     id: (t_idx * 10_000 + i) as u64,
131:                     account_id: (t_idx + 1) as u64,
132:                     amount_cents: amount,
133:                     currency: Currency::Eur,
134:                     status: TxStatus::Initiated,
135:                 };
136:                 let out = proc.process(tx);
137:                 assert_eq!(out.currency, Currency::Eur);
138:             }
139:         }));
140:     }
141: 
142:     for h in handles {
143:         let _ = h.join();
144:     }
145: }
146: 
147: // code_slot: pay_ptp_benchmark
148: #[test]
149: fn pay_ptp_benchmark() {
150:     let slot = "pay_ptp_benchmark";
151:     assert_eq!(slot, "pay_ptp_benchmark");
152: 
153:     run_validation_suite();
154: 
155:     let processor = Arc::new(PaymentProcessor::new(100_000));
156:     run_concurrent_benchmark(&processor);
157: 
158:     let settled = processor.settled_count.load(Ordering::SeqCst);
159:     let rejected = processor.rejected_count.load(Ordering::SeqCst);
160:     let total = settled + rejected;
161: 
162:     assert_eq!(total, 1_000);
163:     assert_eq!(rejected, 100);
164:     assert_eq!(settled, 900);
165:     assert_eq!(processor.total_volume_cents.load(Ordering::SeqCst), 900 * 1_000);
166: }
