8: /// Exhaustive non-allocating parsing errors for zero-copy deserialization.
9: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
10: pub enum ParseError<'a> {
11:     /// Unexpected end of input when more data was required.
12:     UnexpectedEof { expected_bytes: usize },
13:     /// Found an unexpected byte at the given offset.
14:     UnexpectedByte { expected: u8, found: u8, offset: usize },
15:     /// An unrecognized or invalid token string slice.
16:     InvalidToken { token: &'a str, offset: usize },
17:     /// Non UTF-8 byte sequence encountered.
18:     InvalidUtf8 { offset: usize, valid_up_to: usize },
19:     /// Numeric literal parsing failed on slice.
20:     InvalidNumber { raw: &'a str, offset: usize },
21:     /// Provided buffer is smaller than minimum required size.
22:     BufferTooSmall { needed: usize, available: usize },
23:     /// Expected delimiter was not found up to offset.
24:     DelimiterNotFound { delimiter: u8, offset: usize },
25:     /// Magic bytes or header prefix mismatch.
26:     InvalidHeader { header: &'a [u8], offset: usize },
27:     /// Checksum verification failed.
28:     ChecksumMismatch { expected: u32, computed: u32, offset: usize },
29:     /// Recursive structure exceeds maximum nesting depth.
30:     NestingOverflow { max_depth: usize, offset: usize },
31:     /// Extraneous trailing bytes remain after complete parse.
32:     TrailingBytes { remaining: usize, offset: usize },
33: }
34: 
35: pub type ZeroCopyError<'a> = ParseError<'a>;
36: 
37: impl<'a> ParseError<'a> {
38:     pub fn offset(&self) -> Option<usize> {
39:         match self {
40:             Self::UnexpectedEof { .. } | Self::BufferTooSmall { .. } => None,
41:             Self::UnexpectedByte { offset, .. }
42:             | Self::InvalidToken { offset, .. }
43:             | Self::InvalidUtf8 { offset, .. }
44:             | Self::InvalidNumber { offset, .. }
45:             | Self::DelimiterNotFound { offset, .. }
46:             | Self::InvalidHeader { offset, .. }
47:             | Self::ChecksumMismatch { offset, .. }
48:             | Self::NestingOverflow { offset, .. }
49:             | Self::TrailingBytes { offset, .. } => Some(*offset),
50:         }
51:     }
52: 
53:     pub fn is_eof(&self) -> bool {
54:         matches!(self, Self::UnexpectedEof { .. })
55:     }
56: 
57:     pub fn kind_name(&self) -> &'static str {
58:         match self {
59:             Self::UnexpectedEof { .. } => "UnexpectedEof",
