59:             Self::UnexpectedEof { .. } => "UnexpectedEof",
60:             Self::UnexpectedByte { .. } => "UnexpectedByte",
61:             Self::InvalidToken { .. } => "InvalidToken",
62:             Self::InvalidUtf8 { .. } => "InvalidUtf8",
